contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address newOwner) public payable {
        require(newOwner != address(0));
        require(address(this).balance >= 1);

        // A value-carrying call must revert (setOwner is non-payable)
        bool reverted;
        try c.setOwner{value: 1}(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        require(reverted);

        // After the failed call, ownership control still works:
        // a zero-value setOwner to any address succeeds and takes effect.
        bool ok = c.setOwner(newOwner);
        address current = c.owner();

        assert(ok && current == newOwner);
    }

    receive() external payable {}
}

